    private fun reference(raw:String,c:InboxConversationFilesContext):QualifiedInboxTaskSource {val s=InboxTaskSourceSession();s.bind(c);s.show();val t=s.begin(s.control)!!;s.accept(InboxTaskSource.decode(raw,c)!!,t);s.use(s.control);return s.state.choice!!}
    private suspend fun capture(p:InboxTaskSourceModel){p.read(p.control);p.use(p.control)}
    private class Held(override val grants:List<SyntheticInboxCreateTaskGrant>):SyntheticInboxCreateTaskPort {val attempts=mutableListOf<InboxCreateTaskAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticInboxCreateTaskOutcome>>();override suspend fun execute(a:InboxCreateTaskAttempt):SyntheticInboxCreateTaskOutcome {attempts+=a;return withContext(NonCancellable){CompletableDeferred<SyntheticInboxCreateTaskOutcome>().also {pending+=it}.await()}}}
    @Test fun exactTaskSerializerReceiptIndependentCreateContextOmissionBodyAndUnknown()=runTest {
        val d=JSONObject(fixture("inbox-create-task"));val f=FixtureInboxCreateTaskPort.fromJSON(fixture("inbox-create-task"));val c=context(d.getJSONObject("context"));val ref=reference(d.getString("source_json"),c);val auth=f.grants[0].authorization(c)!!;val review=InboxCreateTaskReview(ref,auth,1)
        val grants=d.getJSONArray("grant_cases");for(i in 0 until grants.length()){val x=grants.getJSONObject(i);val g=x.getJSONObject("grant");assertEquals(x.getBoolean("valid"),SyntheticInboxCreateTaskGrant(g.getInt("business"),g.getInt("conversation"),g.getInt("actor"),g.getBoolean("create")).authorization(c)!=null)}
        val cases=d.getJSONArray("receipt_cases");for(i in 0 until cases.length()){val x=cases.getJSONObject(i);val owner=context(x.getJSONObject("context"));val r=InboxCreateTaskReview(reference(x.getString("source_json"),owner),f.grants[0].authorization(owner)!!,1);val l=InboxCreateTaskLedger();assertEquals(x.getString("name"),x.getBoolean("valid"),InboxCreateTaskReceipt.decode(x.getString("response_json"),l.begin(r)!!)!=null)}
        val l=InboxCreateTaskLedger();val a=l.begin(review)!!;assertEquals(0,JSONObject(a.preparedBody()).length());assertEquals("{}",a.preparedBody());assertEquals("/api/inbox/conversations/901/create-task/",a.path);assertTrue(a.query.isEmpty());assertTrue(a.headers.isEmpty());assertNull(l.begin(review));assertFalse(l.acknowledge(auth,l.visible(auth)!!));l.complete(a,f.execute(a));val known=l.visible(auth)!!;assertEquals(InboxCreateTaskPhase.RESPONSE,known.phase);assertEquals(9901,known.result!!.id);assertEquals(701,known.result!!.client);assertEquals(81,known.result!!.lead);assertEquals(5001,known.result!!.assignee);assertEquals(5001,known.result!!.createdBy);assertEquals("normal",known.result!!.priority);assertNull(known.result!!.dueAt);assertEquals(ref,known.attempt.review.reference);l.complete(a,SyntheticInboxCreateTaskOutcome.Unknown);assertEquals(known,l.visible(auth));assertTrue(l.acknowledge(auth,known))
        val u=l.begin(review)!!;l.complete(u,SyntheticInboxCreateTaskOutcome.Unknown);val unknown=l.visible(auth)!!;val next=c.copy(epoch=901,revision=2);val na=f.grants[0].authorization(next)!!;val nextRef=reference(d.getString("source_json"),next);l.complete(u,f.execute(u));assertEquals(unknown,l.visible(na));assertFalse(l.acknowledge(na,unknown));assertNull(l.begin(InboxCreateTaskReview(nextRef,na,2)));assertEquals(ref,unknown.attempt.review.reference);assertFalse(InboxCreateTaskReview(nextRef,auth,1).valid);assertFalse(review.copy(visit=0).valid)
        assertNull(l.visible(SyntheticInboxCreateTaskGrant(101,901,6001,true).authorization(next)));assertTrue(l.blocked(101,901));assertFalse(l.blocked(202,951))
        for(status in listOf(200,202,204,400,403,409,422,500)){val ledger=InboxCreateTaskLedger();val attempt=ledger.begin(review)!!;val result=f.execute(attempt) as SyntheticInboxCreateTaskOutcome.Response;ledger.complete(attempt,result.copy(status=status));assertEquals(InboxCreateTaskPhase.UNKNOWN,ledger.visible(auth)!!.phase)}
        val reject=InboxCreateTaskLedger();val ra=reject.begin(review)!!;reject.complete(ra,SyntheticInboxCreateTaskOutcome.RejectedWithoutWrite);assertTrue(reject.acknowledge(auth,reject.visible(auth)!!));assertEquals(1,reject.records.size)
    }
    private inner class Reads:InboxRepository {override suspend fun inbox(business:Int)=JsonContracts.inbox(fixture("inbox-$business"));override suspend fun thread(business:Int,id:Int)=JsonContracts.thread(fixture("inbox-$business-$id"))}
    @Test fun actualParentCapturedSourceFreezeBackKnownAckUnknownRereadAndABA()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler));val f=FixtureInboxCreateTaskPort.fromJSON(fixture("inbox-create-task"));val held=Held(f.grants);val m=InboxViewModel(Reads(),files=files(),assignmentRead=APIInboxSelfAssignmentRepository(FixtureInboxSelfAssignmentReadTransport.fromJSON(fixture("inbox-self-assignment"))),assignmentSubmission=FixtureInboxSelfAssignmentPort.fromJSON(fixture("inbox-self-assignment")),taskSourceRead=source(),taskCreateSubmission=held)
        try {m.load(101,900);runCurrent();m.open(901);runCurrent();val original=m.state.thread;val box=m.fileMetadata!!;val model=box.createTask!!;val reader=box.taskSource!!;m.openFiles(m.filesEntryControl);assertNull(reader.state.source);assertFalse(model.canPrepare);val stale=model.control;reader.read(reader.control);model.prepare(model.control);assertNull(model.review);reader.use(reader.control);model.prepare(stale);assertNull(model.review);assertTrue(model.canPrepare);model.prepare(model.control);val review=model.review;val chosen=reader.state.choice;reader.clearChoice(reader.control);reader.read(reader.control);box.load(box.control);box.loadAssignment(box.control);box.prepareAssignment(box.control);assertEquals(review,model.review);assertEquals(chosen,reader.state.choice);assertTrue(model.canSubmit);assertNull(box.assignmentReview);model.back(model.control);assertEquals(chosen,reader.state.choice);assertFalse(reader.controlsBlocked());model.prepare(model.control);val control=model.control;val job=launch {model.submit(control)};runCurrent();val pending=model.record!!;model.submit(model.control);model.acknowledge(pending,model.control);box.load(box.control);assertEquals(chosen,reader.state.choice);assertEquals(1,held.attempts.size);assertTrue(m.conversationCommandsBlocked);assertTrue(reader.controlsBlocked());m.closeFiles(m.filesPresentationControl);m.openFiles(m.filesEntryControl);held.pending[0].complete(f.execute(held.attempts[0]));job.join();val response=model.record!!;assertEquals(InboxCreateTaskPhase.RESPONSE,response.phase);assertEquals(9901,response.result!!.id);assertEquals(701,response.result!!.client);assertEquals(81,response.result!!.lead);assertEquals(original,m.state.thread);model.acknowledge(response,control);assertEquals(response,model.record);model.acknowledge(response,model.control);assertNull(reader.state.source);assertNull(reader.state.choice);assertEquals(1,model.retainedAttemptCount);assertFalse(m.conversationCommandsBlocked)
            capture(reader);model.prepare(model.control);val unknownJob=launch {model.submit(model.control)};runCurrent();held.pending[1].completeExceptionally(IllegalStateException("fake unknown"));unknownJob.join();val unknown=model.record!!;capture(reader);model.acknowledge(unknown,model.control);model.prepare(model.control);assertEquals(unknown,model.record);assertNull(model.review);assertFalse(model.canPrepare);box.loadAssignment(box.control);box.prepareAssignment(box.control);assertNull(box.assignmentReview);m.closeFiles(m.filesPresentationControl);m.load(202,901);runCurrent();m.open(951);runCurrent();m.openFiles(m.filesEntryControl);capture(reader);assertNull(model.record);assertEquals(202,reader.state.choice!!.context.business);m.closeFiles(m.filesPresentationControl);m.load(101,902);runCurrent();m.open(901);runCurrent();m.openFiles(m.filesEntryControl);capture(reader);assertEquals(unknown,model.record);assertTrue(m.conversationCommandsBlocked)
        }finally{Dispatchers.resetMain()}
    }
    @Test fun noPortNoCreateForeignSourceNullRelationsCancellationLateOwnerAndRejected()=runTest {
        val f=FixtureInboxCreateTaskPort.fromJSON(fixture("inbox-create-task"));val a=InboxConversationFilesContext(101,901,903,1);val b=InboxConversationFilesContext(202,951,904,1)
        suspend fun ready(port:SyntheticInboxCreateTaskPort?,c:InboxConversationFilesContext=a):InboxCreateTaskModel {val reader=InboxTaskSourceModel(source());reader.bind(c);reader.show();val model=InboxCreateTaskModel(reader,port);model.commandsBlocked={false};model.bind(c);model.show();capture(reader);return model}
        for(port in listOf(null,Held(emptyList()),Held(listOf(SyntheticInboxCreateTaskGrant(101,901,5001,false))))){val model=ready(port);model.prepare(model.control);assertNotNull(model.source);assertNull(model.review);assertEquals(0,model.retainedAttemptCount)}
        val mismatched=ready(f);mismatched.reader!!.bind(b);mismatched.reader!!.show();capture(mismatched.reader!!);mismatched.prepare(mismatched.control);assertNull(mismatched.review)
        val nulls=ready(f,a.copy(conversation=902));nulls.prepare(nulls.control);nulls.submit(nulls.control);assertEquals(InboxCreateTaskPhase.RESPONSE,nulls.record!!.phase);assertNull(nulls.record!!.result!!.client);assertNull(nulls.record!!.result!!.lead)
        val rejected=ready(f,b);rejected.prepare(rejected.control);rejected.submit(rejected.control);val r=rejected.record!!;assertEquals(InboxCreateTaskPhase.REJECTED,r.phase);rejected.acknowledge(r,rejected.control);assertEquals(1,rejected.retainedAttemptCount);assertFalse(rejected.blocked)
        val cp=Held(f.grants);val cancel=ready(cp);cancel.prepare(cancel.control);val cj=launch {cancel.submit(cancel.control)};runCurrent();cj.cancel();cp.pending[0].complete(f.execute(cp.attempts[0]));cj.join();assertEquals(InboxCreateTaskPhase.UNKNOWN,cancel.record!!.phase);assertEquals(cp.attempts[0],cancel.record!!.attempt)
        val lp=Held(f.grants);val late=ready(lp);late.prepare(late.control);val lj=launch {late.submit(late.control)};runCurrent();late.hide();late.reader!!.bind(b);late.reader!!.show();late.bind(b);late.show();capture(late.reader!!);val before=late.control;val foreign=late.reader!!.state.choice;lp.pending[0].complete(f.execute(lp.attempts[0]));lj.join();assertEquals(before,late.control);assertEquals(foreign,late.reader!!.state.choice);assertNull(late.record);assertEquals(1,late.retainedAttemptCount)
        assertNull(InboxConversationFilesModel(files(),ownerScope=this).createTask)
    }
    @Test fun taskAndAllFourChildCommandsShareUnknownBarrier()=runTest {
        val c=InboxConversationFilesContext(101,901,590,1);val f=FixtureInboxCreateTaskPort.fromJSON(fixture("inbox-create-task"));val clientFixture=FixtureInboxLinkClientPort.fromJSON(fixture("inbox-link-client"));val leadFixture=FixtureInboxLinkLeadPort.fromJSON(fixture("inbox-link-lead"));val held=Held(f.grants);val selectedFixture=FixtureInboxTargetAssignmentPort.fromJSON(fixture("inbox-target-assignment"));val dealFixture=FixtureInboxLinkDealPort.fromJSON(fixture("inbox-link-deal"))
